-- Clinician library catch-up: 50 resources from 2026-10-27 that the database lacked.
-- Generated from data/therapist-resources.json with: python3 tools/therapist_resources_sql.py <the 50 slugs>
-- An upsert on slug, so applying it twice is harmless.
on conflict (slug) do update set
  title      = excluded.title,
  kind       = excluded.kind,
  summary    = excluded.summary,
  goal       = excluded.goal,
  audience   = excluded.audience,
  duration   = excluded.duration,
  body_md    = excluded.body_md,
  fields     = excluded.fields,
  tags       = excluded.tags,
  created_at = excluded.created_at;
